import clsx from "clsx";

export function cx(...classNames: any) {
  // append prefix
  return clsx(...classNames)
    .split(" ")
    .map((className) => `__rrm-${className}`)
    .join(" ");
}

export function getRingSectionPath(
  startAngle: number,
  endAngle: number,
  innerRadius: number,
  outerRadius: number,
  globalCenter?: number
): string {
  const center = globalCenter ?? outerRadius;
  
  // get the x and y coordinates on the outer ring
  const outerX1 = outerRadius * Math.cos(startAngle);
  const outerY1 = outerRadius * Math.sin(startAngle);
  const outerX2 = outerRadius * Math.cos(endAngle);
  const outerY2 = outerRadius * Math.sin(endAngle);

  // get the x and y coordinates on the inner ring
  const innerX1 = innerRadius * Math.cos(startAngle);
  const innerY1 = innerRadius * Math.sin(startAngle);
  const innerX2 = innerRadius * Math.cos(endAngle);
  const innerY2 = innerRadius * Math.sin(endAngle);

  const largeArcFlag = endAngle - startAngle <= 180 ? 0 : 1;

  return `
            M ${center} ${center}
            m ${innerX1} ${innerY1}
            l ${outerX1 - innerX1} ${outerY1 - innerY1}
            A ${outerRadius} ${outerRadius} 0 ${largeArcFlag} 1 ${outerX2 + center} ${outerY2 + center}
            l ${innerX2 - outerX2} ${innerY2 - outerY2}
            A ${innerRadius} ${innerRadius} 0 ${largeArcFlag} 0 ${center + innerX1} ${center + innerY1}
          `;
}

export function getArrowPoints(startAngle: number, endAngle: number, outerRadius: number, globalCenter?: number): string {
  const center = globalCenter ?? outerRadius;
  const outR = outerRadius * 0.98;
  const inR = outerRadius * 0.95;
  const pivotX = outR * Math.cos((startAngle + endAngle) / 2) + center;
  const pivotY = outR * Math.sin((startAngle + endAngle) / 2) + center;
  const x1 = inR * Math.cos((startAngle + endAngle) / 2 + Math.PI / 60) + center;
  const y1 = inR * Math.sin((startAngle + endAngle) / 2 + Math.PI / 60) + center;
  const x2 = inR * Math.cos((startAngle + endAngle) / 2 - Math.PI / 60) + center;
  const y2 = inR * Math.sin((startAngle + endAngle) / 2 - Math.PI / 60) + center;
  return `${x1},${y1} ${pivotX},${pivotY} ${x2},${y2}`;
}

export function calculatePositions(position: string, innerRadius: number, outerRadius: number, globalCenterOffset?: number) {
  let startAngle = 0;
  let endAngle = 0;
  let objectHeight = 0;
  let objectWidth = 0;
  let objectX = 0;
  let objectY = 0;

  const centerOffset = globalCenterOffset ?? outerRadius;

  switch (position) {
    case "top":
      startAngle = Math.PI / 6 + Math.PI;
      endAngle = (5 * Math.PI) / 6 + Math.PI;
      objectHeight = innerRadius / 2;
      objectY = Math.sin(startAngle) * innerRadius + centerOffset - objectHeight;
      objectX = Math.cos(startAngle) * innerRadius + centerOffset;
      objectWidth = Math.cos(endAngle) * innerRadius + centerOffset - objectX;
      break;
    case "bottom":
      startAngle = Math.PI / 6;
      endAngle = (5 * Math.PI) / 6;
      objectHeight = innerRadius / 2;
      objectY = Math.sin(endAngle) * innerRadius + centerOffset;
      objectX = Math.cos(endAngle) * innerRadius + centerOffset;
      objectWidth = Math.cos(startAngle) * innerRadius + centerOffset - objectX;
      break;
    case "left":
      startAngle = (4 * Math.PI) / 6;
      endAngle = (8 * Math.PI) / 6;
      objectWidth = innerRadius / 2;
      objectX = Math.cos(endAngle) * innerRadius + centerOffset - objectWidth;
      objectY = Math.sin(endAngle) * innerRadius + centerOffset;
      objectHeight = Math.sin(startAngle) * innerRadius + centerOffset - objectY;
      break;
    case "right":
      startAngle = (10 * Math.PI) / 6;
      endAngle = (2 * Math.PI) / 6;
      objectWidth = innerRadius / 2;
      objectX = Math.cos(startAngle) * innerRadius + centerOffset;
      objectY = Math.sin(startAngle) * innerRadius + centerOffset;
      objectHeight = Math.sin(endAngle) * innerRadius + centerOffset - objectY;
      break;
    case "center":
      objectX = centerOffset - innerRadius;
      objectY = objectX;
      objectWidth = innerRadius * 2;
      objectHeight = objectWidth;
      break;
    default:
      throw new Error(`Invalid position: ${position}`);
  }
  return { startAngle, endAngle, objectX, objectY, objectWidth, objectHeight };
}

export function getObjectDimensions(
  deltaRadius: number,
  angleStep: number,
  middleRadius: number,
  index: number,
  outerRadius: number,
  globalCenterOffset?: number
) {
  const objectWidth = Math.min(deltaRadius / Math.sqrt(2), angleStep * middleRadius);
  const objectHeight = objectWidth;
  
  const centerOffset = globalCenterOffset ?? outerRadius;
  const objectX = Math.cos(angleStep * index + angleStep / 2) * middleRadius + (centerOffset - objectWidth / 2);
  const objectY = Math.sin(angleStep * index + angleStep / 2) * middleRadius + (centerOffset - objectHeight / 2);
  
  return { objectX, objectY, objectWidth, objectHeight };
}

export function getLayerRadius(layerIndex: number, baseInnerRadius: number, baseOuterRadius: number): {
  innerRadius: number;
  outerRadius: number;
  middleRadius: number;
  deltaRadius: number;
} {
  const deltaRadius = baseOuterRadius - baseInnerRadius;
  
  if (layerIndex === 0) {
    return {
      innerRadius: baseInnerRadius,
      outerRadius: baseOuterRadius,
      middleRadius: (baseInnerRadius + baseOuterRadius) / 2,
      deltaRadius
    };
  }
  
  const layerInnerRadius = baseOuterRadius + (layerIndex - 1) * deltaRadius;
  const layerOuterRadius = layerInnerRadius + deltaRadius;
  
  return {
    innerRadius: layerInnerRadius,
    outerRadius: layerOuterRadius,
    middleRadius: (layerInnerRadius + layerOuterRadius) / 2,
    deltaRadius
  };
}