import React from "react";
import { MenuContext, MenuContextType } from "./MenuContext";
import { MenuDisplayProps } from "./types";
import { calculatePositions, cx } from "./util";

const MenuDisplay = ({ __parentMenuId, __layerIndex, position, onClick, ...props }: MenuDisplayProps) => {
  const { data } = React.useContext(MenuContext) as MenuContextType;
  const { menuStack, drawBackground, maxOuterRadius } = data;
  const [active, setActive] = React.useState(false);
  
  const layerIndex = __layerIndex ?? 1;
  const layerRadius = data.getLayerRadius(layerIndex);
  const { innerRadius, outerRadius } = layerRadius;

  let { startAngle, endAngle, objectX, objectY, objectWidth, objectHeight } = React.useMemo(
    () => calculatePositions(position, innerRadius, outerRadius, maxOuterRadius),
    [position, innerRadius, outerRadius, maxOuterRadius]
  );

  if (!menuStack.includes(__parentMenuId)) {
    return <></>;
  }

  return drawBackground ? (
    <g
      {...props}
      onMouseEnter={() => setActive(true)}
      onMouseLeave={() => setActive(false)}
      onClick={(event) => {
        event.preventDefault();
        event.stopPropagation();
        onClick(event, position);
      }}
    >
      {position !== "center" ? (
        <path
          d={`M ${Math.cos(startAngle) * innerRadius + maxOuterRadius}
                ${Math.sin(startAngle) * innerRadius + maxOuterRadius}
              A ${innerRadius} ${innerRadius} 0 0 1 
                ${Math.cos(endAngle) * innerRadius + maxOuterRadius}
                ${Math.sin(endAngle) * innerRadius + maxOuterRadius}
              Z`}
          className={cx("base", { active })}
        />
      ) : (
        <circle cx={maxOuterRadius} cy={maxOuterRadius} r={innerRadius} className={cx("base", { active })} />
      )}
      <foreignObject x={objectX} y={objectY} width={objectWidth} height={objectHeight}>
        <div className={cx("content", { active })}>
          {props.children ? (
            props.children
          ) : (
            <svg
              className={cx("return", { active })}
              width={`${objectWidth * 0.5}px`}
              height={`${objectHeight * 0.5}px`}
              viewBox="0 0 48 48"
            >
              <path d="M12.9998 8L6 14L12.9998 21" />
              <path d="M6 14H28.9938C35.8768 14 41.7221 19.6204 41.9904 26.5C42.2739 33.7696 36.2671 40 28.9938 40H11.9984" />
            </svg>
          )}
        </div>
      </foreignObject>
    </g>
  ) : (
    <g {...props}>
      <foreignObject
        x={objectX}
        y={objectY}
        width={objectWidth}
        height={objectHeight}
        onMouseEnter={() => setActive(true)}
        onMouseLeave={() => setActive(false)}
        onClick={(event) => {
          event.preventDefault();
          event.stopPropagation();
          onClick(event, position);
        }}
      >
        <div className={cx("content", { active })}>
          {props.children ? (
            props.children
          ) : (
            <svg
              className={cx("return", { active })}
              width={`${objectWidth * 0.5}px`}
              height={`${objectHeight * 0.5}px`}
              viewBox="0 0 48 48"
            >
              <path d="M12.9998 8L6 14L12.9998 21" />
              <path d="M6 14H28.9938C35.8768 14 41.7221 19.6204 41.9904 26.5C42.2739 33.7696 36.2671 40 28.9938 40H11.9984" />
            </svg>
          )}
        </div>
      </foreignObject>
    </g>
  );
};

export default MenuDisplay;