import React from "react";
import { MenuContext, MenuContextType } from "../MenuContext";
import { SubMenuProps } from "../types";
import { SubMenuClosed } from "./SubMenuClosed";
import { SubMenuOpened } from "./SubMenuOpened";

const SubMenu = (props: SubMenuProps) => {
  const { data, pushMenu, getLayerIndex } = React.useContext(MenuContext) as MenuContextType;
  const { menuStack } = data;
  const myMenuId = `${props.__parentMenuId}-${props.__index}`;
  const parentLayerIndex = props.__layerIndex ?? 0;
  const myLayerIndex = parentLayerIndex + 1;
  const isCurrentTopMenu = menuStack[menuStack.length - 1] === myMenuId;
  const isInStack = menuStack.includes(myMenuId);

  const { __parentMenuId, displayPosition, children, displayView, onDisplayClick, ...rest } = props;

  if (!isInStack || myLayerIndex >= data.maxLayers) {
    return <SubMenuClosed {...rest} __myMenuId={myMenuId} __layerIndex={parentLayerIndex} />;
  }
  
  return (
    <SubMenuOpened
      __myMenuId={myMenuId}
      __parentMenuId={__parentMenuId}
      __layerIndex={myLayerIndex}
      displayPosition={displayPosition}
      children={children}
      displayView={displayView}
      onDisplayClick={onDisplayClick}
    />
  );
};

export default SubMenu;