import React from "react";
import { MenuContext, MenuContextType } from "../MenuContext";
import { SubMenuClosedProps } from "../types";
import { cx, getArrowPoints, getObjectDimensions, getRingSectionPath } from "../util";

export const SubMenuClosed = ({
  __myMenuId,
  __parentMenuId,
  __angleStep,
  __index,
  __layerIndex,
  itemView,
  data: propsData,
  onItemClick,
  ...props
}: SubMenuClosedProps) => {
  const { data, pushMenu, selectItem } = React.useContext(MenuContext) as MenuContextType;
  const { maxOuterRadius, selectedItemId } = data;
  const [active, setActive] = React.useState(false);
  const angleStep = __angleStep as number;
  const index = __index as number;
  const myMenuId = __myMenuId as string;
  const parentMenuId = __parentMenuId as string || 'unknown';
  const layerIndex = __layerIndex as number ?? 0;

  const layerRadius = data.getLayerRadius(layerIndex);
  const { innerRadius, outerRadius, middleRadius, deltaRadius } = layerRadius;

  const itemId = `${parentMenuId}-${index}`;
  const isSelected = selectedItemId === itemId;

  const { objectX, objectY, objectWidth, objectHeight } = React.useMemo(
    () => getObjectDimensions(deltaRadius, angleStep, middleRadius, index, outerRadius, maxOuterRadius),
    [deltaRadius, angleStep, middleRadius, index, outerRadius, maxOuterRadius]
  );

  return data.drawBackground ? (
    <g
      {...props}
      className={cx(props.className as string, { selected: isSelected })}
      onMouseEnter={(e) => {
        props.onMouseEnter?.(e);
        setActive(true);
      }}
      onMouseLeave={(e) => {
        props.onMouseLeave?.(e);
        setActive(false);
      }}
      onClick={(event) => {
        event.preventDefault();
        event.stopPropagation();
        selectItem(itemId);
        onItemClick?.(event, index, propsData);
        pushMenu(myMenuId);
      }}
    >
      <path
        d={getRingSectionPath(index * angleStep, (index + 1) * angleStep, innerRadius, outerRadius, maxOuterRadius)}
        className={cx("base", { active, selected: isSelected })}
      />
      <foreignObject x={objectX} y={objectY} width={objectWidth} height={objectHeight}>
        <div className={cx("content", { active, selected: isSelected })}>{itemView}</div>
      </foreignObject>
      <polyline
        points={getArrowPoints(index * angleStep, (index + 1) * angleStep, outerRadius, maxOuterRadius)}
        className={cx("arrow", { active, selected: isSelected })}
      />
    </g>
  ) : (
    <g {...props} className={cx(props.className as string, { selected: isSelected })}>
      <foreignObject
        onMouseEnter={(e) => {
          props.onMouseEnter?.(e);
          setActive(true);
        }}
        onMouseLeave={(e) => {
          props.onMouseLeave?.(e);
          setActive(false);
        }}
        onClick={(event) => {
          event.preventDefault();
          event.stopPropagation();
          selectItem(itemId);
          onItemClick?.(event, index, propsData);
          pushMenu(myMenuId);
        }}
        x={objectX}
        y={objectY}
        width={objectWidth}
        height={objectHeight}
      >
        <div className={cx("content", { active, selected: isSelected })}>{itemView}</div>
      </foreignObject>
      <polyline
        points={getArrowPoints(index * angleStep, (index + 1) * angleStep, outerRadius, maxOuterRadius)}
        className={cx("arrow", { active, selected: isSelected })}
      />
    </g>
  );
};