import React from "react";
import { MenuContext, MenuContextType } from "./MenuContext";
import { MenuItemProps } from "./types";
import { cx, getObjectDimensions, getRingSectionPath } from "./util";

const MenuItem = ({ __angleStep, __index, __parentMenuId, __layerIndex, data: propsData, onItemClick, ...props }: MenuItemProps) => {
  const { data, selectItem } = React.useContext(MenuContext) as MenuContextType;
  const { menuStack, drawBackground, maxOuterRadius, selectedItemId } = data;
  const [active, setActive] = React.useState(false);
  const angleStep = __angleStep as number;
  const index = __index as number;
  const parentMenuId = __parentMenuId as string;
  const layerIndex = __layerIndex as number ?? 0;

  const layerRadius = data.getLayerRadius(layerIndex);
  const { innerRadius, outerRadius, middleRadius, deltaRadius } = layerRadius;

  const isVisible = menuStack.includes(parentMenuId);
  const itemId = `${parentMenuId}-${index}`;
  const isSelected = selectedItemId === itemId;

  if (!isVisible) {
    return <></>;
  }

  const { objectX, objectY, objectWidth, objectHeight } = React.useMemo(
    () => getObjectDimensions(deltaRadius, angleStep, middleRadius, index, outerRadius, maxOuterRadius),
    [deltaRadius, angleStep, middleRadius, index, outerRadius, maxOuterRadius]
  );

  return drawBackground ? (
    <g
      {...props}
      className={cx(props.className as string, { selected: isSelected })}
      onMouseEnter={(e) => {
        props.onMouseEnter?.(e);
        setActive(true);
      }}
      onMouseLeave={(e) => {
        props.onMouseLeave?.(e);
        setActive(false);
      }}
      onClick={(event) => {
        event.preventDefault();
        event.stopPropagation();
        selectItem(itemId);
        onItemClick?.(event, index, propsData);
      }}
    >
      <path
        d={getRingSectionPath(index * angleStep, (index + 1) * angleStep, innerRadius, outerRadius, maxOuterRadius)}
        className={cx("base", { active, selected: isSelected })}
      />
      <foreignObject x={objectX} y={objectY} width={objectWidth} height={objectHeight}>
        <div className={cx("content", { active, selected: isSelected })}>{props.children}</div>
      </foreignObject>
    </g>
  ) : (
    <g {...props} className={cx(props.className as string, { selected: isSelected })}>
      <foreignObject
        x={objectX}
        y={objectY}
        width={objectWidth}
        height={objectHeight}
        onMouseEnter={(e) => {
          props.onMouseEnter?.(e);
          setActive(true);
        }}
        onMouseLeave={(e) => {
          props.onMouseLeave?.(e);
          setActive(false);
        }}
        onClick={(event) => {
          event.preventDefault();
          event.stopPropagation();
          selectItem(itemId);
          onItemClick?.(event, index, propsData);
        }}
      >
        <div className={cx("content", { active, selected: isSelected })}>{props.children}</div>
      </foreignObject>
    </g>
  );
};

export default MenuItem;