import clsx from "clsx";
import React from "react";
import { MenuContext } from "./MenuContext";
import { MenuContextData, MenuProps } from "./types";
import { cx, getLayerRadius } from "./util";

import "./Menu.css";

export const MAIN_MENU_ID = "0";

const initialData: MenuContextData = {
  baseInnerRadius: 0,
  baseOuterRadius: 0,
  deltaRadius: 0,
  menuHeight: 0,
  menuWidth: 0,
  menuStack: [MAIN_MENU_ID],
  maxLayers: 3,
  drawBackground: true,
  getLayerRadius: () => ({ innerRadius: 0, outerRadius: 0, middleRadius: 0, deltaRadius: 0 }),
  maxOuterRadius: 0,
  selectedItemId: null,
};

const Menu = ({
  centerX,
  centerY,
  innerRadius,
  outerRadius,
  animationTimeout,
  show,
  animateSubMenuChange,
  animation,
  theme,
  drawBackground,
  maxLayers = 3,
  ...props
}: MenuProps) => {
  const [data, setData] = React.useState<MenuContextData>(initialData);

  if (innerRadius >= outerRadius) {
    throw new Error("RadialMenu's innerRadius must be less than outerRadius");
  }
  const numOfChildren = React.Children.count(props.children);
  if (numOfChildren < 2) {
    throw new Error("RadialMenu must have at least 2 children");
  }

  const angleStep = (2 * Math.PI) / numOfChildren;
  const deltaRadius = outerRadius - innerRadius;
  
  const maxOuterRadius = outerRadius + (maxLayers - 1) * deltaRadius;
  const menuWidth = maxOuterRadius * 2;
  const menuHeight = menuWidth;

  animationTimeout = React.useMemo(() => animationTimeout || 0, [animationTimeout]);
  const myMenuId = MAIN_MENU_ID;

  const getLayerRadiusCallback = React.useCallback(
    (layerIndex: number) => getLayerRadius(layerIndex, innerRadius, outerRadius),
    [innerRadius, outerRadius]
  );

  React.useEffect(() => {
    setData((prev) => ({
      baseInnerRadius: innerRadius,
      baseOuterRadius: outerRadius,
      deltaRadius,
      menuWidth,
      menuHeight,
      menuStack: show ? [MAIN_MENU_ID] : prev.menuStack,
      maxLayers,
      drawBackground: drawBackground ?? true,
      getLayerRadius: getLayerRadiusCallback,
      maxOuterRadius,
      selectedItemId: show ? null : prev.selectedItemId,
    }));
  }, [innerRadius, outerRadius, show, drawBackground, maxLayers, getLayerRadiusCallback, maxOuterRadius]);

  const [transition, setTransition] = React.useState<"closed" | "closing" | "opened" | "opening">("closed");
  
  const handleTransition = React.useCallback(() => {
    document.documentElement.style.setProperty("--__reactRadialMenu__animation-delay", `${animationTimeout}ms`);
    if (show) {
      setTransition("opening");
      setTimeout(() => setTransition("opened"), animationTimeout);
    } else {
      setTransition("closing");
      setTimeout(() => setTransition("closed"), animationTimeout);
    }
  }, [show, animationTimeout]);

  const pushMenu = React.useCallback(
    (menuId: string) => {
      setData((prev) => {
        const newStack = [...prev.menuStack];
        if (newStack.length < prev.maxLayers && !newStack.includes(menuId)) {
          newStack.push(menuId);
        }
        return { ...prev, menuStack: newStack };
      });
    },
    []
  );

  const popMenu = React.useCallback(() => {
    setData((prev) => {
      const newStack = [...prev.menuStack];
      if (newStack.length > 1) {
        newStack.pop();
      }
      return { ...prev, menuStack: newStack };
    });
  }, []);

  const getLayerIndex = React.useCallback(
    (menuId: string): number => data.menuStack.indexOf(menuId),
    [data.menuStack]
  );

  const selectItem = React.useCallback(
    (itemId: string) => {
      setData((prev) => ({
        ...prev,
        selectedItemId: prev.selectedItemId === itemId ? null : itemId,
      }));
    },
    []
  );

  const clearSelection = React.useCallback(() => {
    setData((prev) => ({
      ...prev,
      selectedItemId: null,
    }));
  }, []);

  React.useEffect(() => {
    handleTransition();
  }, [show, handleTransition]);

  if (transition === "closed") {
    return <></>;
  }

  return (
    <MenuContext.Provider value={{ data, pushMenu, popMenu, getLayerIndex, selectItem, clearSelection }}>
      <svg
        {...props}
        width={menuWidth}
        height={menuHeight}
        viewBox={`-3 -3 ${menuWidth + 6} ${menuHeight + 6}`}
        style={{
          ...props.style,
          width: `${menuWidth}px`,
          height: `${menuHeight}px`,
          left: `${centerX - maxOuterRadius}px`,
          top: `${centerY - maxOuterRadius}px`,
        }}
        className={clsx(props.className, cx("menu", transition, animation, theme, !data.drawBackground && "no-bg"))}
      >
        {React.Children.map(props.children, (child, index) => {
          if (React.isValidElement(child)) {
            let prop = {
              __index: index,
              __angleStep: angleStep,
              __parentMenuId: myMenuId,
              __layerIndex: 0,
            };
            return React.cloneElement(child, prop);
          }
          return child;
        })}
      </svg>
    </MenuContext.Provider>
  );
};

export default Menu;